    variant = pick_variant(_TAKEG_TEMPLATES, rng)
    values = {
        "<": character_name,
        "[": victim_name,
        "[1": victim_name,
        "]": f"{victim_name}'s",
        "#": str(gold_amount),
    }
    return render(variant, values, rng=rng)


