def describe_give(
    result: TradeExecutionResult,
    *,
    giver_name: str,
    recipient_name: str,
    item_name: str | None = None,
    gold_requested: int | None = None,
    rng: random.Random,
) -> str | None:
    """Assembles the one-sentence Give narrative from an already-computed
    ``TradeExecutionResult`` (``turn/trade_execution.py execute_give()``,
    Phase 133, item path closed Phase 140) -- the same "data first,
    already-computed result in, prose out" pattern ``describe_battle()``
    above already established for battle outcomes.

    - A successful item transfer (``result.item_transferred``) renders
      ``_LTrade`` -- needs a caller-supplied ``item_name``. As of Phase
      214, ``describe_turn_results()`` resolves this itself via
      ``models/treasure.py TREASURE_NAME[result.item.treasure]``
      (``result.item`` is the real transferred ``ItemInstance``, now
      kept on ``TradeExecutionResult``); a direct caller with no
      ``TradeExecutionResult.item`` still needs to supply ``item_name``
      itself, and gets ``None`` back without one rather than a guess.
    - A successful gold transfer (``result.gold_transferred > 0``)
      renders ``_LGGive``.
    - A failure specifically because the giver's treasury didn't cover
      [3.18]'s 10%-cap (``execute_gold_give()``'s own
      ``"exceeds 10% treasury cap"`` reason string) renders ``_LNHave``
      -- needs a caller-supplied ``gold_requested`` (the original
      decoded amount, not the cap itself); returns ``None`` without one.
    - Every other failure reason (giver/recipient not found, not
      co-located, recipient not a King, no recipient decoded) has no
      sourced narrative template at all and renders nothing -- this
      project doesn't invent administrative-error prose.
    """

    if result.applied and result.item_transferred:
        if item_name is None:
            return None
        return render_item_give(giver_name, recipient_name, item_name, rng)

    if result.applied and result.gold_transferred > 0:
        return render_gold_give(giver_name, recipient_name, result.gold_transferred, rng)

    if not result.applied and result.reason is not None and result.reason.startswith("exceeds 10% treasury cap"):
        if gold_requested is None:
            return None
        return render_insufficient_gold(giver_name, gold_requested, rng)

    return None


# Office.CURATOR's own real perk (Phase 667) has no surviving POWMSG/
# SAY.PAS template anywhere in the available source -- neither AKGEN's
# disassembly reports nor AKPROSE's catalog transcription name a
# distinct narrative string for this outcome (only the same title-grant
# paragraph `OFFICE_TITLE_DESCRIPTION` already quotes). This sentence is
# **project-original**, clearly labeled as such per this project's own
# "confirmed-unsourced gap" convention -- replace it if a real source
# ever surfaces.
CURATOR_RESEARCH_TEMPLATE = "The Guild of Sages researched item number # for <: it is a \\."


def render_curator_research(researcher_name: str, item_number: int, item_name: str, rng: random.Random) -> str:
    values = {"<": researcher_name, "#": str(item_number), "\\": item_name}
    return render(CURATOR_RESEARCH_TEMPLATE, values, rng=rng)


def describe_curator_research(
    result: CuratorResearchResult, *, researcher_name: str, rng: random.Random
) -> str | None:
    """Assembles the Curator-research narrative from an already-computed
    ``CuratorResearchResult`` (``turn/trade_execution.py execute_
    curator_research()``, Phase 667). A failed lookup (``result.reason``
    -- no ``ItemInstance`` exists for the requested number) has no
    sourced failure narrative either, so it renders nothing, the same
    "no template, no invented administrative-error prose" convention
    ``describe_give()`` above already uses.
    """

    if not result.applied or result.treasure is None:
        return None
    return render_curator_research(researcher_name, result.item_id, TREASURE_NAME[result.treasure], rng)


# HostAK/TP/PROSE/FRUMOR.X -- the rumor narrative (Phase 243's own
# resolve_rumor_generation()). The real Pascal sentence always names
# *both* the guardian and the treasure in one clause ("& inhabited by
# +, who guards the \") -- but Phase 243's own confirmed design reveals
# only one of the two per rumor (70% monster, 30% item). Adapted per
# the user's own confirmed resolution to this conflict: every clause
# that doesn't touch the omitted detail stays verbatim (including the
# source's own double-space idiosyncrasies), only the tail clause
# naming the omitted detail is dropped/replaced. Two variant sets, not
# one, as a result -- FRUMOR.X's own 4 sentences, each split in two.
_FRUMOR_MONSTER_TEMPLATES: list[str] = [
    "{While carousing/Rdrinking with fellow/Rother adventurers/Rtravellers in a bar/Rtavern, }< heard {mention/Rtell "
    "}of a{n interesting} feature in  $#:  & inhabited/Roccupied by the +.",
    "{While }conversing/Rspeaking with {passing/Rfriendly }merchants/Radventurers, < heard/Rlearned a rumor about a "
    "previously/Rheretofore unknown/Runheard_of § in  $#, held/Rinhabited by the +.",
    "< heard a rumor telling of a{ perilous} feature in  $#{ previously unknown to us},  & inhabited_by/Rwhere_dwells the +.",
    "{while }talking/Rspeaking to some {friendly }locals/Rfarmers, < heard a rumor about  & in  $#, "
    "occupied/Rinhabited by the +.",
]

_FRUMOR_ITEM_TEMPLATES: list[str] = [
    "{While carousing/Rdrinking with fellow/Rother adventurers/Rtravellers in a bar/Rtavern, }< heard {mention/Rtell "
    "}of a{n interesting} feature in  $#:  & is said/Rrumored to hold the \\.",
    "{While }conversing/Rspeaking with {passing/Rfriendly }merchants/Radventurers, < heard/Rlearned a rumor about a "
    "previously/Rheretofore unknown/Runheard_of § in  $#, reputed/Rsaid to contain the \\.",
    "< heard a rumor telling of a{ perilous} feature in  $#{ previously unknown to us},  the § is reputed to "
    "contain the \\.",
    "{while }talking/Rspeaking to some {friendly }locals/Rfarmers, < heard a rumor about  & in  $#. "
    "They/Rsome say/Rmaintain that the § holds the \\.",
]


def describe_rumor(rumor: Rumor, state: GameState, character_name: str, board_width: int, rng: random.Random) -> str:
    """Assembles the one-sentence Rumor narrative from an already-generated
    ``Rumor`` (``turn/rumor.py resolve_rumor_generation()``, Phase 243).

    Unlike ``describe_give()``/``describe_hire()``, this takes ``state``
    directly (matching ``render_bystander_spell_notice()``'s own
    "needs to re-resolve a coordinate" precedent) rather than plain
    caller-supplied strings for every field: the feature's own *kind*
    is never falsified by Phase 243's own design (only the guardian/
    treasure/province can be), so it's always looked up straight from
    ``state.features[rumor.feature_id]`` rather than threaded through
    ``Rumor`` itself. ``#`` (`report/prose.py`'s own "a number" marker)
    renders the raw hex location code FRUMOR.X's own ``$#`` uses for an
    unvisited province (the ``$`` is a literal character already in the
    template, matching Pascal's own hex-literal notation, not a second
    marker) -- ``turn/hex_numbering.py encode_hex_number()``, the exact
    inverse of the decode every LMOVE order already uses.

    **2026-11-20 bug fix, user-confirmed via a live playtest**: this
    used to render the raw hex code *unconditionally*, even when
    ``rumor.described_coord`` names a province this same Kingdom
    already knows by name (`turn/rumor.py``'s own "possibly false"
    province substitution picks uniformly from *every* province on the
    map, with no regard to whether this Kingdom has ever been there --
    `described_coord`'s own docstring already says as much). Real
    provinces always have a name from world generation onward
    (`worldgen/generate_new_game.py` calls `turn/rename_province.py
    assign_province_name()` for every one of them up front, not
    lazily on first discovery) -- a raw hex code was never really
    standing in for "no name exists yet," only for "this Kingdom
    doesn't know it yet." So the "$#" raw-hex-code half of the
    template is now used only when ``ProvinceState.known_to_kingdom()``
    says this Kingdom genuinely doesn't know the province yet; the "@"
    (province name) marker swaps in for it otherwise.

    Dispatches on ``rumor.content`` (``RumorContent.FEATURE_AND_MONSTER``
    -> ``MONSTER_NAMES[rumor.described_monster]``, ``RumorContent.ITEM``
    -> ``TREASURE_NAME[rumor.described_treasure]``) -- exactly one of the
    two ever gets named, per this module's own Phase 244 addendum above.
    Prints whatever ``rumor`` says without regard to ``rumor.is_true``:
    a false rumor is supposed to read exactly like a true one to the
    kingdom that heard it, that's the entire point of it being false.
    """

    feature = state.features[rumor.feature_id]
    feature_name = FEATURE_TYPE_NAMES[feature.kind]
    values = {"<": character_name, "&": feature_label(feature)}
    if rumor.content is RumorContent.FEATURE_AND_MONSTER:
        values["+"] = MONSTER_NAMES[rumor.described_monster]
        variant = pick_variant(_FRUMOR_MONSTER_TEMPLATES, rng)
    else:
        values["\\"] = TREASURE_NAME[rumor.described_treasure]
        variant = pick_variant(_FRUMOR_ITEM_TEMPLATES, rng)

    described_province = state.provinces.get(rumor.described_coord)
    if (
        described_province is not None
        and described_province.name is not None
        and described_province.known_to_kingdom(rumor.kingdom_id)
    ):
        variant = variant.replace("$#", "@")
        values["@"] = described_province.name
    else:
        values["#"] = str(encode_hex_number(rumor.described_coord, board_width))
    return render(variant.replace("§", feature_name), values, rng=rng)


# HostAK/TP/PROSE/FINDFEAT.X -- the in-person discovery narrative
# (Phase 245), FRUMOR.X's own sibling: a character physically standing
# in the province, so the real template uses "@" (resolved province
# name) rather than FRUMOR.X's "$#" (raw hex number for an unvisited
# one). Unlike FRUMOR.X, the real sentence never mentions a treasure at
# all -- only the feature and its guardian monster -- so this is a
# straight, unmodified 4-variant transcription, no FRUMOR.X-style
# adapt-and-split needed. Quoted in full:
#   < discovered/Rfound a{n interesting} feature in @:  &  inhabited/Roccupied by +.
#   < discovered/Rlocated  previously/Rheretofore unknown/Runheard_of &  in @, held/Rinhabited by +.
#   < was informed/Rtold by some peasants/Rsheepherders of  {perilous }feature in @{ previously unknown to us},  &  inhabited_by/Rwhere_dwells +.
#   < {also }found/Rdiscovered  &  in @, occupied/Rinhabited by +.
_FINDFEAT_TEMPLATES: list[str] = [
    "< discovered/Rfound a{n interesting} feature in @:  &  inhabited/Roccupied by the +.",
    "< discovered/Rlocated  a previously/Rheretofore unknown/Runheard_of §  in @, held/Rinhabited by the +.",
    "< was informed/Rtold by some peasants/Rsheepherders of a{ perilous} feature in @{ previously unknown to us},  "
    "&  inhabited_by/Rwhere_dwells the +.",
    "< {also }found/Rdiscovered  &  in @, occupied/Rinhabited by the +.",
]


def feature_label(feature: Feature) -> str:
    """How the original's reports name a feature: article, name and number --
    "an Altar (#97)", "a Glade (#126)"."""

    name = FEATURE_TYPE_NAMES[feature.kind]
    article = "an" if name[:1].upper() in "AEIOU" else "a"
    return f"{article} {name} (#{feature.feature_id})"


def render_monster_description(monster: Monster) -> str:
    """Renders MONSTERS.X2's own flavor-text sentence(s) for ``monster``
    (Phase 613) -- rulebook [3.2]'s own line, "Monsters are described
    when they are first discovered" (``SAY.PAS:790 _LMDesc``). Plain
    verbatim text, no ``render()`` needed: not one of ``MONSTER_
    DESCRIPTION``'s own 60 real entries carries a ``/R``/``{}`` choice
    marker (confirmed by grep), so there's nothing to vary and no
    ``rng`` parameter, the same "nothing to vary" shape ``render_magic_
    feature_discovery()`` already established.

    "First discovered" is read here as *this in-person discovery
    event* (the same moment ``describe_feature_discovery()`` itself
    fires from, immediately below) rather than "the first time this
    Kingdom has ever seen this monster species" -- the rulebook gives
    no threshold, and this project has no per-Kingdom "monster species
    already seen" tracking anywhere to gate a stricter reading on
    (confirmed absent by grep) -- inventing one would be exactly the
    kind of unsourced state-tracking mechanism this project's own "no
    source, no guess" discipline avoids. If a real source ever
    surfaces confirming the stricter "once per species" reading, this
    is the one place to revisit.
    """

    return MONSTER_DESCRIPTION[monster]


def describe_feature_discovery(feature: Feature, character_name: str, province_name: str, rng: random.Random) -> list[str]:
    """Renders FINDFEAT.X's sentence for a feature just found in person --
    ``turn/exploration.py discover_features()`` (Phase 242), now surfaced
    to a caller via ``turn/move_execution.py KingdomExplorationResult``/
    ``report/turn_report.py ExploreResult.discovered_features`` (Phase
    245, closing the "record exists, no consumer yet" gap the EXPLORE
    dispatch branch left open since Phase 242).

    Assumes ``feature.guardian_monster`` is set -- true for every
    feature ``turn/world_generation.py`` ever creates (Phase 242
    confirmed every generated feature always gets a guardian), and the
    real template never has a treasure-only branch to fall back to
    (unlike FRUMOR.X's own rumor sentence, Phase 244) -- a feature built
    by a test or caller with no guardian isn't a valid input here.

    Returns two lines as of Phase 613: FINDFEAT.X's own discovery
    sentence, then ``render_monster_description()``'s own MONSTERS.X2
    flavor text for the guardian -- two separate ``SAY.PAS`` dispatch
    calls (``_LFind``/``_LMDesc``), not one concatenated fragment (see
    that function's own docstring for the "which discovery event"
    judgment call this rests on).
    """

    feature_name = FEATURE_TYPE_NAMES[feature.kind]
    monster_name = MONSTER_NAMES[feature.guardian_monster]
    values = {"<": character_name, "@": province_name, "&": feature_label(feature), "+": monster_name}
    variant = pick_variant(_FINDFEAT_TEMPLATES, rng).replace("§", feature_name)
    return [render(variant, values, rng=rng), render_monster_description(feature.guardian_monster)]


# HostAK/TP/PROSE/FSEARCH.X -- the Search-attempt opening sentence. See
# module docstring's Phase 156 addendum.
_FSEARCH_TEMPLATES: list[str] = [
    "< approached/Rinvestigated the &, intending/Rmeaning to root_out/Runcover its mysteries/Sdark_secrets.",
    "< searched/Rapproached the & with every/Rthe intention of overcoming/Rprevailing_over it and whatever "
    "{vile }guardian {beast }lay within{ it}.",
    "< unsheathed/Rgirded > weapon and entered the & warily/Rcautiously.",
    "< downed/Rtook ^A {deep/Rlarge, }nervous draught/Rgulp from > flask/Rbottle of {old }vodka/Rscotch, "
    "and entered/Rapproached the &.",
    "< gathered > courage {and > wits }and {cautiously/Rnervously }entered the &.",
]


def render_search_attempt(character_name: str, feature_name: str, rng: random.Random, *, is_sea: bool = False) -> str:
    """Renders FSEARCH.X's sentence for the Search-attempt opening moment
    (``SAY.PAS`` ``_LSearch: FD('fsearch',S_Adv,10)``). ``feature_name``
    is ``PROSE.TXT``'s own ``&`` marker (Feature name -- ``report/
    prose.py``'s own marker table). ``is_sea`` (Phase 74) resolves the
    "/S" marker the first variant carries.
    """

    variant = pick_variant(_FSEARCH_TEMPLATES, rng)
    values = {"<": character_name, ">": f"{character_name}'s", "&": feature_name}
    return render(variant, values, rng=rng, is_sea=is_sea)


# HostAK/TP/SAY.PAS _LSacked -- a single, real, hardcoded template (no
# file). See module docstring's Phase 156 addendum.
SEARCH_FEATURE_ALREADY_SACKED_TEMPLATE = (
    "< searched/Rscouted_out the & but it {apparently }had {already }been looted/Rsacked."
)


def render_search_feature_already_sacked(character_name: str, feature_name: str, rng: random.Random) -> str:
    """Renders ``_LSacked``'s sentence for attempting to Search a feature
    that's already been looted (``turn/search_execution.py
    execute_search()``'s own ``"feature already looted"`` rejection).
    """

    values = {"<": character_name, "&": feature_name}
    return render(SEARCH_FEATURE_ALREADY_SACKED_TEMPLATE, values, rng=rng)


# 2026-11-21, project-original text (no sourced template exists -- the
# original only ever narrated a winning channel, see `render_squeeze_
# attack()`): a Hand of Death whose channel was broken by the victim's
# counter-hit, or that never engaged because the target is immune, used to
# leave no trace at all, so a real, slot-consuming cast looked like the
# order had never been carried out. `<` = caster, `[` = target.
HAND_OF_DEATH_INTERRUPTED_TEMPLATE = "[ broke <'s concentration with a counter-blow"
HAND_OF_DEATH_FADED_TEMPLATE = "<'s Hand Of Death spell faded away."
HAND_OF_DEATH_NO_EFFECT_TEMPLATE = "< squeezed <'s fist in vain, for [ is beyond the reach of the Hand Of Death spell."


def render_hand_of_death_channel(
    caster_name: str,
    target_name: str,
    squeeze_hits: tuple[int, ...],
    interrupt_damage: int | None,
    ending: str,
    rng: random.Random,
) -> list[str]:
    """One line per squeeze that landed, then the closing line for how the
    channel ended: ``"won"`` (squeezes only -- the kill follows from the
    caller's own death narration), ``"interrupted"`` (the victim's
    counter-blow, then the spell fading), ``"caster_killed"`` (the
    counter-blow was lethal) or ``"immune"`` (the spell never engaged).
    """

    values = {"<": caster_name, "[": target_name}
    if ending == "immune":
        return [render(HAND_OF_DEATH_NO_EFFECT_TEMPLATE, values, rng=rng)]
    lines = [render_squeeze_attack(caster_name, target_name, rng) + render_attack_hit(target_name, damage, rng) for damage in squeeze_hits]
    if ending in ("interrupted", "caster_killed") and interrupt_damage is not None:
        lines.append(render(HAND_OF_DEATH_INTERRUPTED_TEMPLATE, values, rng=rng) + render_attack_hit(caster_name, interrupt_damage, rng))
    if ending == "interrupted":
        lines.append(render(HAND_OF_DEATH_FADED_TEMPLATE, values, rng=rng))
    return lines


def render_hand_of_death_abort(
    caster_name: str,
    target_name: str,
    squeeze_hits: tuple[int, ...],
    interrupt_damage: int | None,
    rng: random.Random,
) -> list[str]:
    """``render_hand_of_death_channel()`` for a Search channel that did not
    end the fight: ``interrupt_damage`` ``None`` means an immune target.
    """

    ending = "immune" if interrupt_damage is None else "interrupted"
    return render_hand_of_death_channel(caster_name, target_name, squeeze_hits, interrupt_damage, ending, rng)


# 2026-11-21, user-reported (a hero Talked to a Titan: no trace in the
# report of what it said or that it offered a quest). The guardian's own
# MTALK.X2 offer text is already transcribed for every reply
# (`turn/encounter.py MONSTER_TALK_OFFER_TEXT`); only R_RIDDLE/R_VISIT were
# ever surfaced. This narrates the other quest/agreement replies. Markers
# the model has no value for (the item a monster wants brought back, a
# revenge target, a King's title, a terrain) get generic placeholder
# phrases -- project-original, never an invented specific fact, the same
# stance render_guardian_proposes_quest_location() already takes for its
# own unresolvable province.
_TALK_OFFER_PLACEHOLDERS: dict[str, str] = {
    "⟦CTRL-T:treasure-2⟧": "lost relic",
    "⟦CTRL-C:quest-character⟧": "a hated rival",
    "⟦CTRL-K:king-title⟧": "some distant King",
    "⟦CTRL-H:terrain-2⟧": "rugged",
}


def render_guardian_talk_offer(
    character_name: str,
    monster_name: str,
    reply: MonsterTalkReply,
    *,
    province_name: str,
    treasure_name: str,
    feature_name: str,
    rng: random.Random,
) -> list[str]:
    """Two lines: that the character spoke with the guardian, then the
    guardian's own offer (``MONSTER_TALK_OFFER_TEXT[reply]``), with the
    sourced pronoun/place/item markers resolved from real data.
    """

    text = _resolve_ctrl_a_markers(MONSTER_TALK_OFFER_TEXT[reply])
    for marker, placeholder in _TALK_OFFER_PLACEHOLDERS.items():
        text = text.replace(marker, placeholder)
    text = text.replace("FU-lfill", "Fulfill").replace("# gold", "a hefty sum in gold")
    values = {
        "[1": monster_name,
        "[": monster_name,
        "<2": character_name,
        "<": character_name,
        ">": "their",
        "]": "its",
        "@": province_name,
        "\\": treasure_name,
        "&": feature_name,
    }
    offer = render(text, values, rng=rng).strip()
    # The sourced text runs sentences together ("...provinces.Explore").
    offer = re.sub(r'([.!?]"?)(?=[A-Za-z(])', r"\1 ", offer)
    offer = offer[0].upper() + offer[1:]
    return [f"{character_name} spoke with {monster_name}.", offer]


def describe_search(
    result: SearchExecutionResult,
    *,
    state: GameState | None = None,
    character_name: str,
    feature_name: str,
    rng: random.Random,
    is_sea: bool = False,
) -> list[str]:
    """Assembles Search's own turn-report lines from an already-computed
    ``SearchExecutionResult`` (``turn/search_execution.py
    execute_search()``, Phase 132/154/155), the same "data first,
    already-computed result in, prose out" pattern every other
    ``describe_*`` composer here already establishes.

    - Rejected specifically because the feature was already looted
      (``result.reason == "feature already looted"``) renders
      ``_LSacked`` alone (``render_search_feature_already_sacked()``) --
      the one rejection reason with a real sourced sentence. Every
      other rejection (leader/feature not found, no guardian recorded,
      not co-located) is an internal/engine-level state check, not a
      narrative moment the rulebook describes -- renders nothing, same
      "don't invent administrative-error prose" policy ``describe_give()``
      already states explicitly.
    - Every accepted attempt opens with ``_LSearch``/``FSEARCH.X``
      (``render_search_attempt()``), regardless of whether combat ever
      resolves -- the sentence describes *approaching* the feature, not
      its outcome.
    - **Phase 175: each Fire Arrow shot in ``result.fire_arrow_shots`` is
      narrated individually**, in order, right after the opening line.
      Only the guardian's own shots (``shot.shooter == "b"``, matching
      ``turn/encounter.py EncounterCombatResult``'s own "a"/"b" convention
      where ``a``=leader/``b``=monster, ``turn/search_execution.py``'s own
      Phase 175 addendum) are checked against ``missile_attack_flavor(
      MONSTER_RANGED_WEAPON.get(result.guardian_monster))`` for a species-
      specific dragon-breath/boulder-throw/petrifying-gaze sentence
      (Phase 155's renderers, previously never called from anywhere); the
      leader's own shots (``shooter == "a"``) always use the generic
      ``render_fire_arrow_attack()``/``render_attack_hit()``/
      ``render_attack_missed()`` triplet (Phase 111-112), per the user's
      own footnote wording ("cosa viene scritto quando parte il missile
      [del mostro]" -- what gets written when the monster's own missile
      is fired) -- the flavor describes what the *monster* does, never
      the character. A monster with no flavor mapping (``missile_attack_
      flavor()`` returns ``None`` -- includes Titan/Treant, ``models/
      weapon.py``'s own deliberately-preserved discrepancy, see that
      module's Phase 94 addendum) also falls back to the generic triplet
      for its own shots.
    - **Phase 1027**: a Talk resolving to ``MonsterTalkReply.R_RIDDLE``
      (``result.guardian_riddle is not None``) appends
      ``render_guardian_poses_riddle()``, right after the opening line
      -- the real, already-transcribed ``RIDDLE.X2`` text for whichever
      of the 7 entries ``turn/search_execution.py
      _select_guardian_riddle()`` picked (project-original selection,
      real sourced text; see that function's own docstring). The other
      18 ``QUEST_OR_AGREEMENT`` replies still render nothing at all --
      this project still doesn't narrate those.
    - **Phase 1028**: a Talk resolving to ``MonsterTalkReply.R_VISIT``
      (``result.guardian_quest_location is not None``) appends
      ``render_guardian_proposes_quest_location()``, right after the
      Riddle line above -- the exact sibling treatment for the real,
      already-transcribed ``VISIT.X2`` text for whichever of the 5
      entries ``turn/search_execution.py
      _select_guardian_quest_location()`` picked. See that function's
      and ``render_guardian_proposes_quest_location()``'s own
      docstrings for the sourcing/scope details.
    - A fatal loss (``combat_resolved and winner == "monster" and
      leader_killed``) appends ``render_mortally_wounded()`` -- the same
      already-sourced MORTWOUN.X sentence (Phase 112) every other
      personal-combat death already uses, since [5.0]'s generic
      "until one combatant is killed" rule applies here exactly as
      ``turn/search_execution.py``'s own docstring already states --
      then (Phase 611) ``render_character_death()``, HORDEATH.X's own
      generic closing beat (see ``describe_encounter_combat()``'s own
      Phase 611 note for the sourcing).
    - A win (``winner == "leader"``, ``feature_looted``) or an
      inconclusive fight (``winner is None``) append nothing further
      beyond any shot narration above: no sourced sentence for "you
      defeated the guardian and the treasure is yours" exists anywhere
      in the available archive -- confirmed absent by the same research
      that found Phase 148's own skill-book-read gap (`TREASAB.X2`/
      `TREASURE.X2` are inventory-view text, not a Search-victory
      narration), not merely unsearched.
    - **Phase 413: each round of a winning Hand of Death channel
      (``result.squeeze_hits``) is narrated individually**, right after
      the Fire Arrow shots above, via ``render_squeeze_attack()`` +
      ``render_attack_hit()`` (Hand of Death's own attack always lands,
      so ``render_attack_missed()`` never applies). Whichever side cast
      the winning channel is read straight off ``result.winner`` --
      ``squeeze_hits`` is only ever populated for a winning channel (see
      ``SearchExecutionResult.squeeze_hits``'s own Phase 413 note for
      why an interrupted, non-winning channel isn't captured here).
    - **Phase 415: each ordinary Melee swing (``result.melee_swings``) is
      narrated individually**, right after the Hand of Death/Squeeze
      narration above, via ``render_melee_attack()`` (``SWANGAT.X``,
      Phase 113 -- built but never called from anywhere until this
      phase) + ``render_attack_hit()``/``render_attack_missed()``. Each
      ``MeleeSwing`` already carries its own ``attacker`` (``"a"``/
      ``"b"``), unlike Squeeze's one-directional ``result.winner``
      convention, since ordinary Melee is genuinely bidirectional round
      to round. ``attack_method`` (``PROSE.TXT``'s own ``$S`` marker)
      has no source anywhere in this project -- no per-character weapon
      model exists (``turn/encounter.py Combatant`` carries no weapon
      field) -- so every swing uses the fixed, project-original
      ``_MELEE_ATTACK_METHOD = "Attacked"`` default rather than a
      guessed sourced verb; see that constant's own Phase 415 note.

    **Phase 213: now wired into ``describe_turn_results()``.**
    ``SearchExecutionResult`` gained a ``request`` field (stamped by
    ``plan_dispatch.py _dispatch_search()``), resolving ``feature_id`` ->
    ``GameState.features`` -> a coordinate-based ``feature_name`` (this
    project has no per-feature display-name system, unlike provinces --
    see ``describe_turn_results()``'s own Phase 213 note). Callers with
    direct access to the original ``SearchRequest``/``Feature`` can still
    call this composer directly instead.
    """

    if not result.accepted:
        if result.reason == "feature already looted":
            return [render_search_feature_already_sacked(character_name, feature_name, rng)]
        return []

    lines = [render_search_attempt(character_name, feature_name, rng, is_sea=is_sea)]

    monster_name = MONSTER_NAMES.get(result.guardian_monster, "guardian") if result.guardian_monster is not None else "guardian"
    weapon = MONSTER_RANGED_WEAPON.get(result.guardian_monster) if result.guardian_monster is not None else None
    flavor = missile_attack_flavor(weapon) if weapon is not None else None

    # Phase 1027/1028: Talks resolving to MonsterTalkReply.R_RIDDLE or
    # R_VISIT are the two QUEST_OR_AGREEMENT replies this project
    # narrates at all -- see render_guardian_poses_riddle()'s and
    # render_guardian_proposes_quest_location()'s own docstrings. The
    # other 18 quest/agreement replies still render nothing beyond the
    # opening line above, unchanged.
    if result.guardian_riddle is not None:
        lines.append(render_guardian_poses_riddle(monster_name, result.guardian_riddle))
    if result.guardian_quest_location is not None:
        lines.append(render_guardian_proposes_quest_location(monster_name, result.guardian_quest_location))
    if (
        result.guardian_talk_reply is not None
        and result.guardian_riddle is None
        and result.guardian_quest_location is None
        and state is not None
        and result.guardian_talk_coord is not None
    ):
        treasure = result.guardian_talk_treasure
        lines.extend(
            render_guardian_talk_offer(
                character_name,
                monster_name,
                result.guardian_talk_reply,
                province_name=_province_label(state, result.guardian_talk_coord),
                treasure_name=TREASURE_NAME[treasure] if treasure is not None else "treasure",
                feature_name=feature_name,
                rng=rng,
            )
        )
    # 2026-11-20 bug fix, user-confirmed via a deep audit: Office.
    # PSYCHIC_MAGE's own "senses whether the monster intends to keep
    # its end of the bargain" perk -- see SearchExecutionResult.
    # sensed_fulfill_honor's own docstring for why this is only ever
    # set alongside a newly-struck deal.
    if result.sensed_fulfill_honor is not None:
        lines.append(render_sensed_fulfill_honor(character_name, monster_name, result.sensed_fulfill_honor, rng))
    # 2026-11-20: the two previously-silent "Talk went nowhere" outcomes
    # -- see SearchExecutionResult.talk_language_failure's/talk_ignored's
    # own docstrings. Mutually exclusive by construction (_apply_talk_
    # language_failure() only ever sets one or the other per call).
    if result.talk_language_failure:
        lines.append(render_talk_language_failure(character_name, monster_name, rng))
    elif result.talk_ignored:
        lines.append(render_talk_ignored(character_name, monster_name, rng))

    # Phase 858 (backlog: SBUNGLE.X, the "personal-combat Cast that just
    # fizzles" sentence -- see `SearchExecutionResult.fizzled_spells`'s
    # own docstring for the real, sourced trigger and why it was
    # previously unwired). Placed right after the opening search-attempt
    # line, before any Fire Arrow/Melee narration, matching this project's
    # `describe_encounter_combat()` sibling's own documented placement
    # choice (Cast never needs to close range).
    for side, spell in result.fizzled_spells:
        caster_name = character_name if side == "leader" else monster_name
        lines.append(render_spell_fizzled_in_combat(caster_name, SPELL_NAME[spell], rng))

    for side, hits, interrupt_damage in result.hand_of_death_aborts:
        caster_name, target_name = (character_name, monster_name) if side == "leader" else (monster_name, character_name)
        lines.extend(render_hand_of_death_abort(caster_name, target_name, hits, interrupt_damage, rng))

    for shot in result.fire_arrow_shots:
        if shot.shooter == "b" and flavor == "breath_weapon":
            lines.append(
                render_breath_weapon_hit(monster_name, character_name, shot.damage, rng)
                if shot.hit
                else render_breath_weapon_missed(monster_name, character_name, rng)
            )
        elif shot.shooter == "b" and flavor == "boulder_throw":
            lines.append(
                render_boulder_throw_hit(monster_name, character_name, shot.damage, rng)
                if shot.hit
                else render_boulder_throw_missed(monster_name, character_name, rng)
            )
        elif shot.shooter == "b" and flavor == "petrifying_gaze":
            lines.append(
                render_petrifying_gaze_hit(monster_name, character_name, shot.damage, rng)
                if shot.hit
                else render_petrifying_gaze_missed(monster_name, character_name, rng)
            )
        else:
            attacker_name, defender_name = (monster_name, character_name) if shot.shooter == "b" else (character_name, monster_name)
            attack_line = render_fire_arrow_attack(attacker_name, defender_name, rng)
            attack_line += (
                render_attack_hit(defender_name, shot.damage, rng)
                if shot.hit
                else render_attack_missed(attacker_name, defender_name, "arrow", rng, is_sea=is_sea)
            )
            lines.append(attack_line)

    # Phase 413: each round of a winning Hand of Death channel, narrated
    # individually via render_squeeze_attack() -- the caster's own attack
    # always lands (turn/encounter.py resolve_hand_of_death_channel()'s
    # own docstring), so every entry here always pairs with
    # render_attack_hit(), never render_attack_missed(). Whichever side
    # cast the winning channel is read off result.winner itself (only a
    # winning channel ever populates squeeze_hits at all -- see
    # SearchExecutionResult.squeeze_hits's own Phase 413 note).
    squeeze_attacker, squeeze_defender = (
        (monster_name, character_name) if result.winner == "monster" else (character_name, monster_name)
    )
    for damage in result.squeeze_hits:
        lines.append(render_squeeze_attack(squeeze_attacker, squeeze_defender, rng) + render_attack_hit(squeeze_defender, damage, rng))

    # Phase 415: each Melee swing (result.melee_swings, chronological
    # across every round actually fought at melee range) narrated
    # individually via render_melee_attack() (SWANGAT.X, Phase 113 --
    # built but never called from anywhere until now) + render_attack_
    # hit()/render_attack_missed(). Unlike squeeze_hits (one-directional,
    # tied to result.winner), each MeleeSwing already carries its own
    # attacker ("a"/"b") -- ordinary Melee is genuinely bidirectional
    # round to round, so there's no single "the attacker" to read off
    # result.winner here.
    for swing in result.melee_swings:
        melee_attacker, melee_defender = (
            (character_name, monster_name) if swing.attacker == "a" else (monster_name, character_name)
        )
        attack_line = render_melee_attack(melee_attacker, melee_defender, _MELEE_ATTACK_METHOD, rng)
        attack_line += (
            render_attack_hit(melee_defender, swing.damage, rng)
            if swing.hit
            else render_attack_missed(melee_attacker, melee_defender, "blade", rng, is_sea=is_sea)
        )
        lines.append(attack_line)
        proc_line = render_weapon_proc_line(swing.weapon_proc, melee_attacker, melee_defender, swing.weapon_proc_hit_points, rng)
        if proc_line is not None:
            lines.append(proc_line)

    # Phase 855 (SAY.PAS _LShIce): Ice Suspend's own "fully frozen"
    # branch always simplifies to an immediate win (turn/encounter.py's
    # own Phase 189 addendum) -- render the real narration for *why*,
    # before any fatal-death lines below. The frozen side is whichever
    # side didn't win this encounter.
    if result.ice_suspend_immobilized:
        frozen_name = monster_name if result.winner == "leader" else character_name
        lines.append(render_ice_immobilized(frozen_name, rng))

    if result.combat_resolved and result.winner == "monster" and result.leader_killed:
        lines.append(render_mortally_wounded(character_name, rng, is_sea=is_sea))
        lines.append(render_character_death(character_name, rng))

    # Phase 672/673: the guardian's own pacification, if this encounter
    # triggered one -- real, sourced `SAY.PAS` text as of Phase 673, see
    # `render_guardian_pacified_by_fulfill()`/`render_guardian_
    # intimidated()`/`render_guardian_undeterred()`'s own docstrings.
    if result.guardian_pacified_by_fulfill or result.guardian_intimidated or result.guardian_undeterred:
        province_name = _search_province_name(state, result)
        if result.guardian_pacified_by_fulfill:
            lines.append(render_guardian_pacified_by_fulfill(monster_name, province_name, rng))
        if result.guardian_intimidated:
            lines.append(render_guardian_intimidated(monster_name, province_name, rng))
        if result.guardian_undeterred:
            lines.append(render_guardian_undeterred(monster_name, province_name, rng))

    # Phase 790 (MAGFEAT.X2, Phase 96): a real magic-feature-discovery
    # crossing (see `SearchExecutionResult.magic_feature_discovered`'s
    # own Phase 790 docstring), narrated right before any Feature->Power
    # outcome below -- "found a magic item (or not)" precedes "here's
    # what using it did/needs" in narrative order.
    if result.magic_feature_discovered is not None:
        lines.append(
            render_magic_feature_discovery(
                result.magic_feature_discovered,
                feature_name,
                character_name,
                feature_id=result.request.feature_id if result.request is not None else None,
                is_sea=is_sea,
            )
        )

    # Phase 616: Scout's own Feature -> Power [5.8] outcome, narrated last
    # -- matches the rulebook's own "the computer will simply do your
    # Scout tactic after all other encounter tactics are completed"
    # (quoted in full in `_apply_scout()`'s own docstring). `None` covers
    # every outcome this phase has no recovered POWMSG.X2 id for (see
    # `describe_feature_power_attempt()`'s own docstring) as well as "no
    # Scout discovery this Search happened at all".
    if result.feature_power_outcome is not None:
        power_line = describe_feature_power_attempt(
            result.feature_power_outcome, rng, state=state, character_name=character_name
        )
        if power_line is not None:
            lines.append(power_line)
        # Phase 804: ORAC_POWER's own real "has armies" narration (one
        # `_ArmSay` line per commanded army) -- only ever non-empty when
        # `power_line` above was `None` for a real ORAC_POWER has-armies
        # outcome, vacuous for every other power/outcome.
        lines.extend(describe_feature_power_oracle_power_armies(result.feature_power_outcome, state, rng))
        # Phase 790: the real `_EDesc` "needs more information" pair,
        # for a Scout attempt reaching one of the 8 `SA_ARGUMENT_POWERS`
        # with no real `SA` tactic -- independent of whatever (if
        # anything) `describe_feature_power_attempt()` itself rendered
        # above, since that composer's own contract already returns
        # `None` for this exact refusal (no recovered POWMSG id there).
        lines.extend(describe_feature_power_needs_more_info(result.feature_power_outcome, rng))
        # Phase 801: PCOND.X2's own "terms" (only ever non-empty when
        # `power_line` above was `None` -- a refusal never also
        # succeeds) and MCOND.X2's own "sacrifice accepted" companion
        # (only ever non-empty right after a real success line). Phase
        # 803: `feature_name` reaches the new NeedKing/SameAlign/GTurn
        # branch's own `&` marker (NeedKing's real rejection text only).
        lines.extend(
            describe_feature_power_condition_terms(result.feature_power_outcome, rng, feature_name=feature_name)
        )
        lines.extend(
            describe_feature_power_condition_satisfied(result.feature_power_outcome, rng, character_name=character_name)
        )
    return lines


# HostAK/TP/PROSE/QUOTES.X2 + HostAK/TP/SAY.PAS _SQuote. See
# models/quote.py's own module docstring for the full sourcing and the
# documented "real mechanism, uncomputable real-calendar trigger" split.
def render_quote_of_the_week(index: int) -> list[str]:
    """Renders the "Quote of the Week:" header plus the two source lines
    of :func:`ak_engine.models.quote.quote_of_the_week`'s own block
    ``index`` (0-93), as three separate paragraphs -- matching
    ``_SQuote``'s own ``Say('Quote of the Week:',S_Red)`` header
    followed by ``FD``'s per-line ``PR1`` paragraph break for a
    ``quotes.x2`` block (see the module docstring cited above). Neither
    line is passed through :func:`ak_engine.report.prose.render`: the
    real source data contains none of that engine's marker characters
    (confirmed empirically against all 94 blocks), so marker resolution
    would be a pure no-op here.

    The caller supplies ``index`` directly rather than this function
    computing a calendar-driven rotation itself -- see
    ``models/quote.py``'s own docstring for why ``_SQuote``'s real
    ``qfact`` formula can't be reproduced from a parsed move file alone.
    """

    quote_line, attribution_line = quote_of_the_week(index)
    return ["Quote of the Week:", quote_line, attribution_line]


# HostAK/TP/REPORTS.PAS Desc_Lands's own real "STATE OF THE NATION:"
# header + one fixed flavor paragraph (Phase 561) -- AKGEN_reverse_
# engineering_report (5).md SS29.1/SS86.2: `Desc_Lands` prints this
# unconditionally, immediately before DIPLOMACY, regardless of whether
# an Emperor exists (only IMPERIAL OFFICE REPORT's own position moves
# around it -- see describe_imperial_office_report()'s own docstring
# and compose_letter_report()'s own assembly for that half). Verified
# byte-for-byte identical across 6 real sample files this phase
# (Desktop's own SE3__T1.K2/T2.K1/T2.K2/T2.K3/T3.K2/T5.K2, none with
# an Emperor yet) -- this project's own composer never emitted this
# section at all before now.
_STATE_OF_THE_NATION_HEADER = "STATE OF THE NATION:"
_STATE_OF_THE_NATION_INTRO = (
    "My lord and sovereign, greatest of Kings, I humbly beg thy leave to make "
    "report of matters of this Kingdom that may concern thy divine majesty."
)


def describe_state_of_the_nation_report() -> list[str]:
    """The real "STATE OF THE NATION:" section -- see the module-level
    comment above this function for the full sourcing. Entirely fixed
    text, no `state`/`kingdom_id` needed -- the same "Kingdom-agnostic
    composer" shape `describe_alignment_victory_point_reduction(state)`
    already uses (that one still needs `state`, for the Emperor's own
    Alignment; this one needs nothing at all).
    """

    return [_STATE_OF_THE_NATION_HEADER, _STATE_OF_THE_NATION_INTRO]


# HostAK/TP/REPORTS.PAS Desc_Lands's own Rep_Allies/Begin_List (~line
# 104-119) -- the real "DIPLOMACY" section's own sourced, verbatim
# intro sentences (each rejoined across its own 2 raw WRITELN lines,
# same convention as _ARMIES_REPORT_OPENING) and empty-list fallback.
_DIPLOMACY_ALLIED_INTRO = (
    "My lord, the following Kings have wisely allied with thy ever-victorious majesty:"
)
_DIPLOMACY_WAR_INTRO = (
    "My lord, the following Kings are foolishly at war with thy ever-victorious majesty:"
)
_DIPLOMACY_NEUTRAL_INTRO = (
    "My lord, the following Kings are cautiously neutral with thy ever-victorious majesty:"
)
_DIPLOMACY_NONE_AT_PRESENT = "None at present"


def _kingdom_display_name(
    state: GameState, other_kingdom_id: int, *, king_cache: dict[int, int | None] | None = None
) -> str:
    """`"<name> (#<kingdom_id>)"`, resolving the kingdom's own King via
    `_king_leader_id()` (Phase 217) with a `KingdomState.name` fallback
    -- the bare-name half `_diplomacy_entry()` below extends with the
    real DIPLOMACY-specific enrichment. Also used wherever else this
    project needs to name a kingdom by its King (GIR/battle world
    events), which have no "viewing kingdom" of their own and so can't
    use `_diplomacy_entry()`'s own enrichment.

    ``king_cache`` (Phase 1193 efficiency): optional, see
    `_king_leader_id()`'s own docstring -- only `compose_letter_report()`
    passes one (built once in `orchestrator.py`, shared across every
    Kingdom's own letter report, since that one pass is read-only and
    composed strictly after every turn-processing mutation is done).
    Every other caller (the GIR/battle-world-event recorders above,
    which run *during* active turn processing, before that point) omits
    it and gets the original always-fresh lookup, since a King could
    still change between one recorded event and the next.
    """

    king_id = _king_leader_id(state, other_kingdom_id, cache=king_cache)
    name = state.leaders[king_id].name if king_id is not None else state.kingdoms[other_kingdom_id].name
    return f"{name} (#{other_kingdom_id})"


def _diplomacy_entry(
    state: GameState,
    kingdom_id: int,
    other_kingdom_id: int,
    known_tax: dict[int, int],
    known_treasury: dict[int, int],
    *,
    king_cache: dict[int, int | None] | None = None,
) -> str:
    """One DIPLOMACY entry (Phase 640), extended with `Write_List`'s own
    real per-entry enrichment (`REPORTS.PAS` lines 128-158): tax-base/
    treasury figures when the viewing King himself holds Emperor/
    Treasurer and has known the other kingdom for a full turn
    (`known_tax`/`known_treasury`, `turn/imperial_intelligence.py`,
    Phase 491 -- computed once per report, not per-entry), and an
    alignment sentence for a met Heavenly/Undead kingdom or (with no
    "met" prerequisite at all) a kingdom sharing this one's own
    alignment. `Desc_Align`'s own body writes tax/treasury
    unconditionally on `knowpow`/`knowtreas` regardless of *why* it was
    called, so these three pieces are independently gated here rather
    than behind one combined branch.
    """

    entry = _kingdom_display_name(state, other_kingdom_id, king_cache=king_cache)
    if other_kingdom_id in known_tax:
        entry += f", {known_tax[other_kingdom_id]}g taxbase"
    if other_kingdom_id in known_treasury:
        entry += f", {known_treasury[other_kingdom_id]}g in treasury"
    other_alignment = state.kingdoms[other_kingdom_id].alignment
    viewer_alignment = state.kingdoms[kingdom_id].alignment
    show_alignment = (
        state.has_met(kingdom_id, other_kingdom_id) and other_alignment in (Alignment.DIVINE, Alignment.UNDEAD)
    ) or viewer_alignment == other_alignment
    if show_alignment:
        entry += f" is of {other_alignment.value} alignment."
    return entry


def describe_diplomacy_report(
    state: GameState, kingdom_id: int, *, king_cache: dict[int, int | None] | None = None
) -> list[str]:
    """Assembles the "DIPLOMACY" section (Phase 218) -- Allied/At War/
    Neutral lists of every other kingdom, from this kingdom's own
    point of view.

    **The real procedure tracks a genuine 3-state relation per kingdom
    pair** (`kallst[kng,k2]`, `Write_List(allstate)` called once per
    state value) -- **Phase 1026 closes the gap this docstring used to
    flag here**: `turn/diplomacy.py`'s own RULES.AK [8] state machine
    (`GameState.diplomatic_relation()`) now tracks the real third state
    too (`DiplomaticRelation.ENEMY`, written by a real Break Treat order
    via `turn/diplomacy.py apply_treat_orders()`), so AT WAR renders
    every kingdom this one currently has an Enemy relation with, not
    always empty. A kingdom with no relation ever recorded still reads
    Neutral, matching [8]'s own "all Kings start Neutral" default.

    **The real `Write_List`'s own per-entry enrichment is now modeled
    in full** (Phase 640): a known King's tax-base/treasury figure
    (`_diplomacy_entry()` below, `turn/imperial_intelligence.py`'s
    already-built `known_bordering_kingdom_tax_bases()`/`_treasuries()`
    -- gated on the *viewer's own King himself* currently holding the
    Emperor/Treasurer office, per `Write_List`'s own `prevchar[...]=
    kng` comparison, and having known the other kingdom for a full
    turn) and the alignment note (a met Heavenly/Undead kingdom, or any
    kingdom sharing this one's own alignment with no "met" prerequisite
    at all). An earlier version of this docstring called both blocked
    on "office-holder tracking" and "per-King alignment-visibility
    state this project doesn't model" -- stale even when written:
    `resolve_office_holder()` already existed, and the real alignment
    gate turned out to need no new concept at all, just `GameState.
    has_met()` (Phase 408) plus a direct `KingdomState.alignment`
    comparison (see [[feedback_stale_known_gap_claims]]).

    Each entry's own King is resolved via `_king_leader_id()`
    (Phase 217); a kingdom with no `is_king`-flagged leader recorded
    falls back to its own `KingdomState.name` rather than guessing a
    King's name.
    """

    other_kingdom_ids = sorted(k for k in state.kingdoms if k != kingdom_id)
    allied_ids = [k for k in other_kingdom_ids if state.is_allied(kingdom_id, k)]
    war_ids = [
        k
        for k in other_kingdom_ids
        if not state.is_allied(kingdom_id, k) and state.diplomatic_relation(kingdom_id, k) is DiplomaticRelation.ENEMY
    ]
    neutral_ids = [k for k in other_kingdom_ids if k not in allied_ids and k not in war_ids]

    bounds = MapBounds(state.board_width, state.board_height)
    viewer_king_id = _king_leader_id(state, kingdom_id, cache=king_cache)
    known_tax: dict[int, int] = {}
    known_treasury: dict[int, int] = {}
    if viewer_king_id is not None:
        known_tax = known_bordering_kingdom_tax_bases(state, bounds, viewer_king_id) or {}
        known_treasury = known_bordering_kingdom_treasuries(state, bounds, viewer_king_id) or {}

    # Cosmetic fix (2026-11-14, user-requested): a blank line now
    # separates each intro sentence from its own list/"None at present"
    # fallback, and that block from the next intro -- purely for
    # readability, no wording changed. No trailing blank after the
    # final (Neutral) block: compose_letter_report()'s own between-
    # section spacing already covers that gap.
    lines = ["DIPLOMACY", _DIPLOMACY_ALLIED_INTRO, ""]
    lines.extend(
        [_diplomacy_entry(state, kingdom_id, k, known_tax, known_treasury, king_cache=king_cache) for k in allied_ids]
        or [_DIPLOMACY_NONE_AT_PRESENT]
    )
    lines.append("")
    lines.append(_DIPLOMACY_WAR_INTRO)
    lines.append("")
    lines.extend(
        [_diplomacy_entry(state, kingdom_id, k, known_tax, known_treasury, king_cache=king_cache) for k in war_ids]
        or [_DIPLOMACY_NONE_AT_PRESENT]
    )
    lines.append("")
    lines.append(_DIPLOMACY_NEUTRAL_INTRO)
    lines.append("")
    lines.extend(
        [_diplomacy_entry(state, kingdom_id, k, known_tax, known_treasury, king_cache=king_cache) for k in neutral_ids]
        or [_DIPLOMACY_NONE_AT_PRESENT]
    )

    return lines


# 2026-11-03 -- not from any available source text: the user's own
# direct-play confirmation that a diplomatic relation change is always
# announced this way, at the very top of the affected King's own
# report, whichever side of it they're on. See `GameState.diplomacy_
# relation_change_notices`'s own docstring for what populates this.
# Keyed by ``(old_relation, new_relation)``; a pair with no template
# (nothing else is reachable through either the Break Treat or the
# Treat-driven immediate paths that populate this list, see
# `turn/diplomacy.py apply_treat_orders()`) is silently skipped rather
# than guessed at.
#
# 2026-11-05 -- the two ALLIED entries below close what this comment
# used to call a deliberate gap ("an ordinary Treat-formed alliance...
# was never part of what was reported from play"): that's still true
# for an *ordinary* (non-Druidic) Treat, which stays unannounced here
# (see `GameState.pending_treat_transitions`'s own docstring for why),
# but a *mutual* Treat with at least one Druidic party turned out to be
# announced the same way after all -- confirmed with the user directly,
# not a guess.
_DIPLOMACY_CHANGE_TEMPLATES: dict[tuple[DiplomaticRelation, DiplomaticRelation], str] = {
    (DiplomaticRelation.ALLIED, DiplomaticRelation.NEUTRAL): (
        "My lord, grave tidings: {name} has broken his treaty with us; "
        "relations between our two Kingdoms have cooled to Neutral."
    ),
    (DiplomaticRelation.NEUTRAL, DiplomaticRelation.ENEMY): (
        "My lord, dire tidings: {name} has declared war upon us! We are now at war."
    ),
    (DiplomaticRelation.ALLIED, DiplomaticRelation.ENEMY): (
        "My lord, dire tidings: our alliance with {name} has been shattered; we are now at war."
    ),
    (DiplomaticRelation.NEUTRAL, DiplomaticRelation.ALLIED): (
        "My lord, glad tidings: swayed by Druidic wisdom, {name} has allied with us."
    ),
    (DiplomaticRelation.ENEMY, DiplomaticRelation.ALLIED): (
        "My lord, glad tidings: swayed by Druidic wisdom, our war with {name} has ended in alliance."
    ),
}


def describe_diplomacy_change_notices(state: GameState, kingdom_id: int) -> list[str]:
    """Every ``state.diplomacy_relation_change_notices`` entry touching
    ``kingdom_id`` this turn, rendered as one royal-letter-style
    sentence each -- meant to be read first, ahead of the ordinary
    ACTION REPORT narrative (``compose_letter_report()``'s own call
    site), since the entire reason [8.3] grants an ordinary King's own
    Break Treat a one-turn delay (and an Evil/Undead King's own none at
    all) is so the affected King finds out before, not after, that
    turn's own combat. Rendered for *both* Kings in the pair, regardless
    of which one issued the order, or whether it was a mutual break --
    a deliberate, documented choice (no real sample confirms this either
    way): the issuing King already knows what they ordered, and seeing
    it confirmed here does no harm, while keeping one unconditional rule
    is simpler than adding a second one to suppress it for the issuer.

    No header of its own -- same "folds into the existing ACTION REPORT
    section" placement `describe_valhalla_visit_announcement()` and the
    battle-narrative/blackmail-demand notices right next to it in
    `compose_letter_report()` already use, except prepended rather than
    appended, so it reads first.

    **2026-11-05**: also renders an immediate Druidic *mutual* Treat's
    own new alliance -- a different kind of news (no "finds out before
    combat" urgency behind it, just confirmed directly with the user
    that it's announced the same prominent way) alongside the Break
    Treat case this function was originally built for.
    """

    lines: list[str] = []
    for kingdom_a, kingdom_b, old_relation, new_relation in state.diplomacy_relation_change_notices:
        if kingdom_id not in (kingdom_a, kingdom_b):
            continue
        other_kingdom_id = kingdom_b if kingdom_id == kingdom_a else kingdom_a
        template = _DIPLOMACY_CHANGE_TEMPLATES.get((old_relation, new_relation))
        if template is None:
            continue
        lines.append(template.format(name=_kingdom_display_name(state, other_kingdom_id)))
    return lines


# HostAK/TP/REPORTS.PAS Rep_Econ (~line 272-403) -- the real
# "FINANCES" section's own sourced, verbatim opening and Discoveries
# intro (each rejoined across its own raw WRITELN lines, same
# convention as _ARMIES_REPORT_OPENING).
_FINANCES_OPENING = (
    "O Great One, I submit for thy examination the following figures "
    "concerning the finances of our great nation:"
)
_FINANCES_DISCOVERIES_INTRO = (
    "Our Kingdom is also benefited by the following Discoveries of the Sages:"
)
_FINANCES_NONE_AT_PRESENT = "None at present"


def _discovery_exchange_partners(
    state: GameState, discovery: Discovery, *, giver: int | None = None, receiver: int | None = None
) -> list[int]:
    """The other Kingdom id(s) on the real `kexch[giver,receiver]` side
    of `discovery` not fixed by the caller (Phase 643) -- pass `giver`
    to find who `discovery` was *sent to* (`kexch[giver,x]`), or
    `receiver` to find who it was *received from* (`kexch[x,receiver]`).
    Exactly one of the two must be given.
    """

    if giver is not None:
        return sorted(r for (g, r), d in state.discovery_exchanged_from.items() if g == giver and d == discovery)
    return sorted(g for (g, r), d in state.discovery_exchanged_from.items() if r == receiver and d == discovery)


def _discovery_exchange_line(prefix: str, partners: list[int]) -> str:
    """`"(Received from player(s) #3, 7 by scientific treaty)"` (Phase
    643) -- `REPORTS.PAS`'s own real formatting: only the first partner
    gets the `#` marker, later ones are bare numbers after `", "`.
    """

    first, *rest = partners
    names = f"#{first}" + "".join(f", {other}" for other in rest)
    return f"({prefix} player(s) {names} by scientific treaty)"


def describe_finances_report(
    state: GameState,
    kingdom_id: int,
    rng: random.Random | None = None,
    narrative_out: list[str] | None = None,
) -> list[str]:
    """Assembles the "FINANCES" section (Phase 219) -- a deliberately
    narrow slice of `REPORTS.PAS Rep_Econ`, rendering only the figures
    this project's `GameState` actually has real data for.

    **"Gold in treasury"** (`KingdomState.treasury`, `lgold[kng]`) and,
    as of Phase 225, **"Expected Revenues"** (`Tax_Base(kng)`, real
    source text confirmed verbatim at `REPORTS.PAS` line 319: `'
    Expected Revenues: ',Tax_Base(kng):3`) both render. `Tax_Base`
    itself is never *defined* in any available `.PAS` file -- still
    true, the same citation `describe_armies_report()`'s own docstring
    and `plan_dispatch.py`'s Phase 158 note already established -- but
    Phase 225's `turn/tax_base.py compute_tax_base()` supplies a
    project-original aggregation over the real per-province tax data
    Phases 222-224 recovered, closing this specific line's gap even
    though the real formula's own Pascal source is still lost.

    **"Expected Expenses" (Phase 276)**: `ACost`/`LCost` are still never
    *defined* in any available `.PAS` file (Phase 275's own audit), but
    the user supplied real generated `SE3__T*.K*` sample reports
    (2026-07-29) that let this line's own two components be verified
    directly against actual game output rather than only cited from a
    lost Pascal source -- see `turn/expenses.py compute_expected_
    expenses()`'s own docstring for the full cross-check (army
    maintenance confirmed exact across four independent samples; leader
    maintenance reuses `turn/hire_pay.py required_pay()`, confirmed
    against three of four real Heroes, with one known race-related
    mismatch documented rather than silently accepted).

    **The optional "(Including +5 Black Knights)"/"(Including +10
    Thieves Guild)" notes (Phase 277)**: render right after "Gold in
    treasury" and *before* "Expected Revenues" -- confirmed directly
    against five independent real `SE3__T*.K1` samples (not the position
    Phase 275/276's own notes assumed; that guess, based only on nearby
    Pascal line numbers rather than real generated output, is corrected
    here). One sample (`SE3__T7.K1`) shows the office-holder's own
    ADVENTURE-section narrative announcing the title with no FINANCES
    note yet; the very next turn's own sample (`SE3__T8.K1`, same
    kingdom) shows the note -- the gold bonus, and its note, start
    applying the turn *after* the title is earned, not immediately.
    Wired via `turn/office_holder.py resolve_office_holder()` against
    the newly-modeled `Office.EVIL_KING`/`Office.THIEF_PRINCE` (Phase
    277, `turn/merit_points.py evilking_merit_points()`/`thiefprince_
    merit_points()`) -- King of Pain's own note checks whether this
    kingdom's own King holds `EVIL_KING` directly; Prince of Thieves'
    own note checks whether the `THIEF_PRINCE` holder (King *or* Hero)
    belongs to this kingdom, matching `REPORTS.PAS`'s own `LKing(
    titchar[ThiefPrince]) = kng` check (the gold always credits the
    holder's own King's kingdom, even when a Hero holds the title).

    **Phase 435**: all three gold figures ("Gold in treasury"/"Expected
    Revenues"/"Expected Expenses") are now right-justified to the real
    `:3` field width, confirmed verbatim at `REPORTS.PAS` lines 314/319/
    322 (`WRITELN(playfile,'  Gold in treasury:  ',lgold[kng]:3)` and
    its two siblings) -- previously rendered unpadded.

    **Phase 268 closes the "+Invention Bonus" line and the Discoveries
    of the Sages list**, both previously confirmed-absent (no per-
    kingdom Discovery-tracking field existed anywhere in this project
    before Phase 266's `KingdomState.discoveries`). `+Invention Bonus`
    only renders when `compute_invention_bonus_percent()` is positive
    (`IF Inv_Bonus(kng) > 0`, real Pascal text quoted in `models/
    discovery.py`'s own module docstring); the Discoveries list renders
    one real report line per owned Discovery (`describe_discovery_line()`,
    sorted the real way via `sorted_kingdom_discoveries()`), falling back
    to `_FINANCES_NONE_AT_PRESENT` only when the kingdom holds none.

    **Phase 670 adds the real monster-raid/Thunderbird-intervention
    narration** (``turn/monster_raids.py``, ``Desktop/THUNDERBIRD.md``
    sections 12.1/12.2) -- right after "Expected Revenues" (the real
    Pascal `_LFRaid`/`_LFThun` events are logically about this same
    turn's own revenue collection), filtered to `state.turn_raid_
    events` whose own province this kingdom owns. This also resolves
    this module's own former "no recoverable trigger probability or
    magnitude" note in `turn/tax_base.py`'s docstring.

    **Phase 643 adds the real Scientific Treaty exchange attribution**:
    up to two extra lines right after a given Discovery's own name/
    effect line -- `"(Received from player(s) #k1[, k2...] by
    scientific treaty)"` when `GameState.discovery_exchanged_from`
    records another Kingdom as this one's most recent source for it
    (`_discovery_exchange_partners()`/`_discovery_exchange_line()`
    below), and independently `"(Sent to player(s) #k1[, k2...] by
    scientific treaty)"` for the reverse direction -- both, one, or
    neither can appear per Discovery. `REPORTS.PAS`'s own internal
    `Elite_On`/`Imp_Code`/`Check_DSpab` block in the same real
    procedure produces no visible report text at all (confirmed by
    tracing its own governing condition precisely) -- deliberately not
    modeled, the same "internal messaging, not player-facing" stance
    already established elsewhere in this project (e.g. the DIPLOMACY
    composer's own `mknext1`/`Imp_Code` note).

    **Phase 747** (`Desktop/INVBONUS.md`) moves `+Invention Bonus: N%`
    to sit immediately after `Expected Revenues`, matching the exact
    `REPORTS.PAS` order quoted in `models/discovery.py`'s own docstring
    (`Expected Revenues` -> `Inv_Bonus` -> nothing else in between in the
    real source) -- previously rendered after `Expected Expenses`, a
    stale ordering this same docstring's own quoted source already
    contradicted. Also adds a new `_LRev` line (`render_finance_revenue()`,
    Phase 124, wired here for the first time) right after the raid/
    blackmail explanatory lines and before `Expected Expenses`, using
    `state.turn_revenue_credited`'s own real, final per-kingdom total
    (`turn/tax_base.py apply_turn_revenue()`) -- omitted entirely when
    that `GameState` never ran `apply_turn_revenue()`.

    **Phase 771 wires three of the four remaining dormant `SAY.PAS`
    financial-narrative renderers** (`_LFinance`/`_LLCosts`/`_LACosts`/
    `_LTreas`, Phase 124's own addendum): `render_finance_report_
    opening()` right after `_FINANCES_OPENING` (a second, `SAY.PAS`-
    sourced framing sentence naming the King/Kingdom, following the
    `REPORTS.PAS`-sourced one, before any figures); `render_finance_
    leader_costs()`/`render_finance_army_costs()` right after the
    existing `_LRev` line and before `Expected Expenses` -- continuing
    the "revenue narrated, now costs narrated, then the fixed Expected-
    Expenses summary line" flow `_LRev` already established -- gated on
    `state.turn_maintenance_by_kingdom` (Phase 771, `turn/expenses.py
    apply_turn_maintenance()`'s own now-persisted result) having a real
    entry for this kingdom, the identical "omitted entirely when never
    ran" convention `_LRev` already uses; `render_finance_treasury()` as
    the section's very last line, after the Discoveries-of-the-Sages
    list -- the natural closing statement of the financial narrative,
    mirroring how `_LRev` was placed as the closing statement of the
    revenue half. No source stitches these five `SAY.PAS` sentences into
    one fixed sequence (Phase 124's own note), so this placement is a
    documented, reasonable interpretation, not a proven fact.

    `_AUnpaid` (the fifth dormant renderer, "...armies had to go without
    pay") stays deliberately unwired: `turn/expenses.py`'s own docstring
    already confirms army maintenance is paid as one unconditional lump
    sum with no source describing armies going unpaid -- no real trigger
    exists for this sentence in the current model.

    **Phase 791 wires the last dormant renderer, `describe_desertions()`**
    (Phase 599, `LDESERT.X`/`SAY.PAS _LDesert`) -- right after the
    leader/army-cost lines above, inside the same `state.turn_
    maintenance_by_kingdom` gate, since a Hero's desertion is a direct
    narrative consequence of *this exact* `MaintenanceResult`'s own
    unpaid-pay roll (`turn/expenses.py apply_turn_maintenance()`'s own
    Phase 527 mechanic) -- the natural place for it once that data is
    already in scope, rather than a separate report section with no
    equivalent already-flowing data to hook into. `king_name` is this
    same composer's own already-resolved King display name -- correct
    by construction, since `state.turn_maintenance_by_kingdom[kingdom_
    id]`'s own `deserted_leader_ids` are, by definition, Heroes who just
    left *this* Kingdom's own service.
    """

    kingdom = state.kingdoms[kingdom_id]
    rng = rng if rng is not None else random.Random()
    king_name = _leader_name(state, _king_leader_id(state, kingdom_id)) or kingdom.name
    # 2026-11-21: in the original the narrative sentences ("Here is the
    # financial report for X's kingdom: this turn, the Kingdom collected ...
    # X was left with N gold in the treasury.") are one paragraph of the
    # ACTION REPORT, not part of the FINANCES section -- a caller passing
    # ``narrative_out`` receives them there, in order, and the section keeps
    # only the figures.
    narrative = narrative_out if narrative_out is not None else None

    # Cosmetic fix (2026-11-14, user-requested): blank lines now separate
    # the opening paragraph, the figures block, the Discoveries intro,
    # the Discoveries list/"None at present", and the closing treasury
    # sentence -- purely for readability, no wording changed.
    lines = ["FINANCES", _FINANCES_OPENING]
    opening_sentence = render_finance_report_opening(king_name, rng)
    if narrative is not None:
        narrative.append(opening_sentence)
        lines.append("")
    else:
        lines.extend([opening_sentence, ""])
    lines.append(f"Gold in treasury: {kingdom.treasury:>3}")
    evilking_holder = resolve_office_holder(state, Office.EVIL_KING)
    if evilking_holder is not None and state.leaders[evilking_holder.leader_id].kingdom_id == kingdom_id:
        lines.append("(Including +5 Black Knights)")
    thiefprince_holder = resolve_office_holder(state, Office.THIEF_PRINCE)
    if thiefprince_holder is not None and state.leaders[thiefprince_holder.leader_id].kingdom_id == kingdom_id:
        lines.append("(Including +10 Thieves Guild)")
    lines.append(f"Expected Revenues: {compute_tax_base(state, kingdom_id):>3}")
    invention_bonus_percent = compute_invention_bonus_percent(kingdom)
    if invention_bonus_percent > 0:
        lines.append(f"+Invention Bonus: {invention_bonus_percent}%")
    story_sink = narrative if narrative is not None else lines
    for raid_event in state.turn_raid_events:
        province = state.provinces.get(raid_event.province_coord)
        if province is None or province.owner_kingdom_id != kingdom_id:
            continue
        province_name = _province_label(state, raid_event.province_coord)
        monster_name = MONSTER_NAMES[raid_event.monster]
        is_sea = province.effective_terrain() is Terrain.SEA
        if raid_event.kind == "thunderbird":
            story_sink.append(render_thunderbird_intervention(province_name, monster_name, rng))
        else:
            story_sink.append(render_monster_raid(province_name, monster_name, raid_event.damage, rng, is_sea=is_sea))
    for penalty in state.turn_blackmail_penalties:
        if penalty.kingdom_id != kingdom_id:
            continue
        story_sink.append(render_blackmail_penalty(penalty.amount, penalty.blackmailer_kingdom_id, rng))
    if kingdom_id in state.turn_revenue_credited:
        story_sink.append(render_finance_revenue(state.turn_revenue_credited[kingdom_id], rng))
    maintenance = state.turn_maintenance_by_kingdom.get(kingdom_id)
    if maintenance is not None:
        army_cost = compute_army_maintenance(state, kingdom_id)
        story_sink.append(render_finance_leader_costs(maintenance.debited - army_cost, rng))
        story_sink.append(render_finance_army_costs(army_cost, rng))
        story_sink.extend(describe_desertions(maintenance, state, king_name=king_name, rng=rng))
    lines.append(f"Expected Expenses: {compute_expected_expenses(state, kingdom_id):>3}")
    lines.append("")
    lines.append(_FINANCES_DISCOVERIES_INTRO)
    lines.append("")
    if kingdom.discoveries:
        for discovery in sorted_kingdom_discoveries(kingdom.discoveries):
            lines.append(describe_discovery_line(discovery))
            received_from = _discovery_exchange_partners(state, discovery, receiver=kingdom_id)
            if received_from:
                lines.append(_discovery_exchange_line("Received from", received_from))
            sent_to = _discovery_exchange_partners(state, discovery, giver=kingdom_id)
            if sent_to:
                lines.append(_discovery_exchange_line("Sent to", sent_to))
    else:
        lines.append(_FINANCES_NONE_AT_PRESENT)
    treasury_sentence = render_finance_treasury(king_name, kingdom.treasury, rng)
    if narrative is not None:
        narrative.append(treasury_sentence)
    else:
        lines.append("")
        lines.append(treasury_sentence)
    return lines


# HostAK/TP/REPORTS.PAS Rep_Provs (~lines 404-450) -- the real "PROVINCES"
# section's own sourced, verbatim opening, rejoined across its 2 raw
# WRITELN lines (same convention as _ARMIES_REPORT_OPENING/_FINANCES_OPENING).
_PROVINCES_OPENING = (
    "O superfluous one, I have kept well a list of all provinces which have had "
    "the wisdom to submit to thy yoke.  Here, then, are the lands of thy Empire:"
)

_PROVINCES_NONE_AT_PRESENT = "None at present"

# REPORTS.PAS Rep_Provs, lines 436-439, verbatim (both raw WRITELN
# strings, not rejoined -- these are two separate output lines, not one
# wrapped sentence like `_PROVINCES_OPENING` above). Phase 288 wires
# these in for real, alongside the fixed-width row format and the tax-
# tier sort order they head -- see `describe_provinces_report()`'s own
# docstring.
_PROVINCES_COLUMN_CAPTION = "                                                    Recruiting Types:"
_PROVINCES_COLUMN_HEADER = "Province            Tax   Race   Terrain  Expl%     Type 1     Type 2"

# REPORTS.PAS line 426-427: `Min(11,ptax[px,py] + 8*ord((px = bornx[kng])
# and (py = borny[kng])))` -- see this module's own Phase 288 docstring
# addendum for the full derivation.
_PROVINCE_TAX_TIER_HOME_BONUS = 8
_PROVINCE_TAX_TIER_MAX = 11


def _province_tax_tier(province: ProvinceState, coord: HexCoord, kingdom: KingdomState) -> int:
    """REPORTS.PAS's own `Min(11,ptax + 8*is_home_province)` tier formula (Phase 288).

    `province_tax_yield()` returning `None` (no real-world-file data
    bridged for this province) falls back to 0 for this sort-order
    computation only -- a presentation placement, not an assertion that
    the province's real tax is zero (the same "no data isn't a true
    zero" stance this module already takes for the Tax *column* itself,
    which still omits the figure entirely when unknown).
    """

    tax_yield = province_tax_yield(province) or 0
    home_bonus = _PROVINCE_TAX_TIER_HOME_BONUS if coord == kingdom.home_province else 0
    return min(_PROVINCE_TAX_TIER_MAX, tax_yield + home_bonus)


def describe_provinces_report(state: GameState, kingdom_id: int) -> list[str]:
    """Assembles the "PROVINCES" section (Phase 220) -- a deliberately
    narrower slice of `REPORTS.PAS Rep_Provs`, the same "narrower than
    the real procedure, documented why" precedent `describe_armies_report()`
    and `describe_adventure_report()` already established.

    **Sourced and rendered**: every province this kingdom owns
    (`ProvinceState.owner_kingdom_id == kingdom_id`), one fixed-width
    row each -- name (or a `(x, y)` coordinate fallback, the same
    convention `describe_armies_report()` already uses for an unnamed
    province), race (`RACE_NAME`), terrain (`TERRAIN_NAME`, via
    `effective_terrain()` so a cast Part Sea/Flood is reflected -- not
    `illusory_terrain`, which only deceives *outside* observers and must
    never leak into a kingdom's own report of its own land), and percent
    explored (`explored_percent`; the real `pex[px,py]` is a single
    per-province value, not per-kingdom, matching this project's
    already-modeled scalar field rather than `explored_percent_by_kingdom`).

    **Tax and Recruiting Types, Phase 278**: the real table's **Tax**
    column (`ptax[px,py]`, via `turn/tax_base.py province_tax_yield()`,
    the same scar-terrain/Bless/Earthquake-adjusted figure `compute_tax_
    base()` already sums) and **Recruiting Types** columns (`Mod_PAT(px,
    py,0)`/`Mod_PAT(px,py,1)`, via `ProvinceState.recruit_type_1`/
    `recruit_type_2` and `ARMY_TYPE_DESIGNATION`) render whenever known.
    Phase 220/275 called both "confirmed absent" -- true only of a
    Pascal *formula* (neither `ptax` nor `Mod_PAT` is ever computed
    anywhere in the surviving archive, still the case). What Phase 275's
    audit didn't re-check: `parser/gw_world.py`/`gw_world_bridge.py`
    (Phase 222-224, 278) already recover both real values straight from a
    `GW3`-family world file, the same "world-gen-only data, sourced from
    a real snapshot rather than a formula" category `name` closed in
    Phase 150 -- see that module's own docstring for the full,
    zero-conflict decode evidence. Both render blank (the fixed-width
    field's own empty string, not a fabricated zero) for a province
    whose `GameState` was never bridged from a real world file (`tax is
    None`/`recruit_type_1 is None`) -- no data isn't a true zero, the
    same stance `turn/tax_base.py` itself already takes. `recruit_type_2`
    prints only when known and not the real "no second recruit type"
    case -- both look identical from a caller's perspective (nothing to
    show), so this composer doesn't need to distinguish them (see
    `ProvinceState.recruit_type_2`'s own docstring).

    **Type 2 terrain "(Sea)" parenthetical (`pt2`), Phase 282/283**:
    **Phase 723 correction** -- a real data source for `pt2` DOES exist
    after all (`parser/gw_world.py GWProvinceRecord.alternate_terrain`,
    parsed since Phase 373; bridged into `ProvinceState.is_island` by
    `parser/gw_world_bridge.py bridge_gw_world_provinces()`'s own Phase
    723 addendum) -- only the *formula* for what a real `Sea`+`pt2`
    province's tax/mechanics should be remains genuinely unrecovered
    (`worldgen/province_tax.py`'s own docstring). **The rendering format
    below is unchanged, confirmed directly with the user this same
    session (2026-09-03)**: their own real-report example (`"Jungle
    (Sea)"`, 2026-07-29) governs over a separate, freshly-recovered
    literal `REPORTS.PAS` quote (`Desktop/PROGRAMMA AK/SCAR.md`) showing
    a different, separately-indented `"(<pt2-terrain> Island)"` line --
    do not reopen this format question without a new, explicit user
    decision. What renders (`ProvinceState.is_island`, appended as
    `" (Sea)"` right after the terrain name -- Type 1, the land terrain,
    is `terrain_name` itself; Type 2, `is_island`, renders as the
    literal string `"Sea"`) reflects an optional Super AK variant rule
    (games up to 24 players): a province that's half Sea, half its own
    land terrain, where armies fight at a blended half-land/half-Sea
    strength (`turn/strength.py compute_effective_strength()`'s own
    `is_island` parameter; overflight-air units -- Dragons, Eagles --
    are exempt, the user's own words). Set either at world-creation time
    via `turn/island_provinces.py apply_island_provinces()` (an
    exact-count picker, not a percentage, for a hand-built/synthetic
    world) or bridged directly from a real GW world file's own `pt2`
    value (Phase 723) -- never inferred at runtime either way.

    **The real table's own "Type 1"/"Type 2" column pair is a different,
    unrelated pair of columns** -- the user's own real-report header,
    `"Province Tax Race Terrain Expl% Type 1 Type 2"`, confirms these
    hold the Recruiting Types (`Mod_PAT`, e.g. `"Legion"`/`"Fleet"`),
    already rendered here in their own dedicated columns (Phase 278) --
    not terrain at all. The Island-province Type 1/Type 2 terrain split
    lives entirely inside the single `Terrain` column instead
    (`"Jungle (Sea)"`), matching this composer's own one-row-per-
    province shape.

    **Fixed-width columns and tax-tier grouping, Phase 288**: both were
    previously left as documented "presentation choice, not a missing
    data gap" omissions, the same way every other section composer in
    this module treats fixed-width formatting -- closed now, directly
    from `REPORTS.PAS Rep_Provs` (~lines 425-445), quoted here in full:
    ```
    FOR tt:= 11 DOWNTO 0 DO FOR px:= left TO right DO FOR py:= top TO bottom DO
        IF powner[px,py] = kng THEN IF Min(11,ptax[px,py] +
            8*ord((px = bornx[kng]) and (py = borny[kng]))) = tt THEN BEGIN
          ...
          WRITELN(playfile,pname^[px,py],'':20-Length(pname^[px,py]),ptax[px,py]:3,
            rname[Mod_PRace(px,py)]:8,tername[pterr[px,py]]:9,pex[px,py]:6,'%',
            atdesig[Mod_PAT(px,py,0)]:11,atdesig[Mod_PAT(px,py,1)]:11);
    ```
    Reading this directly (rather than the earlier docstring's own
    paraphrase, which turns out to have overstated it) settles two
    things this project previously had wrong or unconfirmed:
    - **No per-tier subheading exists at all.** The column header
      (`_PROVINCES_COLUMN_CAPTION`/`_PROVINCES_COLUMN_HEADER`) prints
      exactly once, guarded by a `none`-style "have we printed anything
      yet" flag that's shared across the *entire* province list, not
      reset per tier. "Grouped by descending tax tier" means only that
      the `tt` loop (11 downto 0) determines row *order* -- it produces
      no visible boundary text between tiers. This corrects this
      module's own earlier "subheadings per tier" description, which
      was written before this project had direct access to
      `REPORTS.PAS` and turns out to have been an overstatement.
    - **The tier itself** is `min(11, tax + 8)` *only for whichever
      province is this kingdom's own home province* (`px = bornx[kng]
      and py = borny[kng]`) -- every other owned province's tier is
      just its own `tax` (still capped at 11). `_province_tax_tier()`
      implements this exactly; sort key is `(-tier, x, y)`, i.e.
      descending tier (matching `tt` counting down from 11), then
      ascending coordinate within a tier (matching the `px`/`py` loops'
      own ascending `left TO right`/`top TO bottom` order) -- the same
      role `describe_armies_report()`'s own coordinate sort played
      before this phase, now demoted to a tie-breaker instead of the
      primary key.

    Fixed-width fields follow the Pascal `:N` widths literally: name
    left-justified in 20, Tax/Race/Terrain/Expl%/Type-1/Type-2 right-
    justified in 3/8/9/6/11/11 respectively (Python's own `str.ljust`/
    `str.rjust` never truncate a longer value either, the same "overflow
    past the field width, don't cut it" behavior Pascal's `:N` already
    has -- relevant here since an Island's own `"Jungle (Sea)"` terrain
    string is wider than its 9-char field). A missing Tax/Type-1/Type-2
    value renders as blank spaces filling that same field width, not a
    fabricated figure -- the column header/caption above them are
    literal, hand-aligned Pascal strings in their own right and aren't
    derived from these same field-width computations, so the two need
    not (and in the real source don't) align to the same character
    columns.
    """

    kingdom = state.kingdoms[kingdom_id]
    lines = ["PROVINCES", _PROVINCES_OPENING]

    owned = [
        (coord, province)
        for coord, province in state.provinces.items()
        if province.owner_kingdom_id == kingdom_id
    ]
    if not owned:
        lines.append(_PROVINCES_NONE_AT_PRESENT)
        return lines

    owned.sort(key=lambda entry: (-_province_tax_tier(entry[1], entry[0], kingdom), entry[0].x, entry[0].y))

    lines.append(_PROVINCES_COLUMN_CAPTION)
    lines.append(_PROVINCES_COLUMN_HEADER)

    for coord, province in owned:
        province_label = province.name if province.name else f"({coord.x}, {coord.y})"
        race_name = RACE_NAME[province.race]
        terrain_name = TERRAIN_NAME[province.effective_terrain()]
        if province.is_island:
            terrain_name += " (Sea)"

        tax_yield = province_tax_yield(province)
        tax_field = f"{tax_yield:>3}" if tax_yield is not None else " " * 3

        type1_name = ARMY_TYPE_DESIGNATION[province.recruit_type_1] if province.recruit_type_1 is not None else ""
        type2_name = ARMY_TYPE_DESIGNATION[province.recruit_type_2] if province.recruit_type_2 is not None else ""

        lines.append(
            f"{province_label:<20}{tax_field}{race_name:>8}{terrain_name:>9}"
            f"{province.explored_percent:>6}%{type1_name:>11}{type2_name:>11}"
        )

    return lines


# Phase 981: the Birthright (Turn 0) report's own per-direction home-
# province neighbor paragraph -- real, sourced text that was never wired
# into this composer at all before this phase. `turn/movement.py`'s own
# Phase 314 addendum already quotes this exact paragraph (from 5 real
# `SE3__T0.K*` samples the user supplied directly), but only as evidence
# for reverse-engineering hex adjacency -- it never actually generated
# this paragraph in a report. Cross-referencing all 5 samples (24
# individual neighbor descriptions total) against each other confirms:
#
# - **A fixed opening clause per compass position** (not per-report --
#   the same position always opens the same way within one sample, the
#   real variation is *between* different Kings' own reports, which
#   this implementation doesn't reproduce -- see below).
# - **The ending sentence depends on the neighbor's own race, not on
#   whether it's currently claimed**: a `HUMANOID_RACES` neighbor (Human/
#   Elf/Dwarf/Orc) always ends "Their <adjective> warriors fight as
#   <recruit types>." -- even when unclaimed (real example: Macondo
#   (#205), Orcs, "where no one rules.  Their Orcish warriors prefer to
#   fight in the style of Phalanx."). A non-humanoid neighbor (Eagles,
#   Dragons, Were-Beasts in the real samples) always ends "...they can
#   muster an army of <race> to defend their province." instead -- real
#   monster races have no organized "warriors" of their own.
# - **"Ruled by no one"** is independent of the above -- any unclaimed
#   neighbor's ruler clause says so, civilized or not.
# - **The board's own top/bottom edge collapses the NE+NW (or,
#   symmetrically, SE+SW) pair into one line**: confirmed directly for
#   the north case (a home province on `y == 0` drops its NE sentence
#   entirely and replaces NW's with "To the north lay an icy expanse
#   which extends as far as the eye can see." -- real sample, Birchwood
#   (#0301)). The south case is this project's own inference by hex-
#   geometric symmetry (`_EVEN_ROW_OFFSETS`/`_ODD_ROW_OFFSETS` both give
#   NE/NW the same `dy` and SE/SW the same, opposite `dy`, regardless of
#   row parity -- see `turn/movement.py neighbor_in_direction_wrapped()`),
#   not independently confirmed by a real sample reaching the board's
#   own bottom row.
#
# **Deliberately not reproduced** (documented gaps, not oversights):
# - The real reports vary several synonyms this implementation fixes to
#   one choice per slot: the opening verb ("Looking to"/"Turning to" the
#   northeast), the ruled-by/owed-allegiance verb for the home province's
#   own intro sentence, "warriors"/"fighters", "fight as"/"array
#   themselves as"/"array themselves in the style of", and the muster
#   sentence's own "an army of"/"a host of"/"they can call on". A
#   prosperity adjective ("rich"/"poor"/"prosperous"/"scenic", seen on
#   both the home province's own intro and some neighbors) isn't
#   reproduced either -- no reliable tax-tier-to-adjective formula could
#   be calibrated from only 5 samples, and showing one sometimes and not
#   others would look like a bug, not a feature.
# - One real sample (Belladonna, #0302) shows a neighbor at the SE
#   position using what is everywhere else this project's own NW-shaped
#   template ("a Forest area owned by no one, where Werefolk dwell")
#   instead of SE's own usual shape -- a single anomalous data point out
#   of 24, read as further confirmation of inter-report randomization
#   this implementation doesn't attempt to reproduce (see above), not a
#   second per-direction shape to add.
# - The real paragraph is a raw, column-wrapped character stream (even
#   splitting one real word, "southwestern", mid-word across a line
#   break) -- `textwrap.wrap()` below word-wraps instead, matching the
#   real ~77-column width without that artifact.

_NEIGHBOR_OPENERS: dict[Direction, str] = {
    Direction.NE: "Looking to the northeast, one can see",
    Direction.E: "To the east lies",
    Direction.SE: "Southeast of here lies",
    Direction.SW: "Viewing the southwestern horizon, one can see",
    Direction.W: "To the west there lies",
    Direction.NW: "Northwest of here is",
}

_NORTH_ICE_CAP_LINE = "To the north lay an icy expanse which extends as far as the eye can see."
_SOUTH_ICE_CAP_LINE = "To the south lay an icy expanse which extends as far as the eye can see."


def real_province_number(coord: HexCoord) -> str:
    """The real province-number convention confirmed by `turn/movement.py`'s
    own Phase 314 addendum (`x*100 + y`, each zero-padded to 2 digits
    before concatenation, e.g. ``(3, 5)`` -> ``"0305"``) -- distinct
    from, and not reusing, `turn/hex_numbering.py encode_hex_number()`'s
    own row-major formula, an earlier hypothesis Phase 314 superseded.

    Public (no leading underscore) since this is also the real "#<N>"
    number the GM webapp's own Move-order province dropdown shows
    (``webapp/moves_compose.py``, sourced directly from the user,
    2026-10-26: "il numero d'ordine della provincia come nell'AK
    originale") -- not to be confused with that same dropdown's own
    internal destination encoding, which still goes through `turn/
    hex_numbering.py encode_hex_number()` unchanged (a different,
    separately-confirmed scheme -- see that function's own docstring).
    """

    return f"{coord.x:02d}{coord.y:02d}"


def _neighbor_ending(race: Race, race_plural: str, race_adjective: str, province: ProvinceState) -> str:
    if race in HUMANOID_RACES:
        # The real paragraph's own full army-type names ("Heavy
        # Cavalry") -- not `ARMY_TYPE_DESIGNATION`'s abbreviated table
        # column form ("Hvy Cav") the PROVINCES table above uses.
        type1 = ARMY_TYPE_NAME[province.recruit_type_1] if province.recruit_type_1 is not None else None
        type2 = ARMY_TYPE_NAME[province.recruit_type_2] if province.recruit_type_2 is not None else None
        types = " and ".join(t for t in (type1, type2) if t)
        if types:
            return f"Their {race_adjective} warriors fight as {types}."
        return f"Their {race_adjective} warriors stand ready to defend their province."
    return f"If need be, they can muster an army of {race_plural} to defend their province."


def _independent_lord_ruler_name(state: GameState, coord: HexCoord) -> str | None:
    """2026-11-20 bug fix, user-confirmed (live AK0 playtest): a
    neutral province governed by an independent lord
    (``worldgen/leader_placement.py independent_lord_effects()``, Phase
    426, wired via ``generate_new_game.py``'s own ``commanded_by``
    linkage, PR #91) has no ``owner_kingdom_id`` at all -- deliberately,
    since that field is this project's own real index into
    ``state.kingdoms`` and an independent lord's own ``leader_id`` isn't
    one (see that PR's own reasoning). ``_describe_neighbor_sentence()``
    above only ever checked ``owner_kingdom_id``, so every one of these
    provinces rendered "ruled/owned by no one" at Turn 0 even when a
    real lord governs it -- user's own words: "nel turno zero dovrebbe
    essere scritto quale eroe è al comando delle province neutrali."

    Only safe to call for the Turn 0 report specifically (this
    function's only real caller, ``describe_home_province_neighbors()``
    -- never wired into any later-turn composer): before any order has
    ever run, an independent lord's own ``LeaderState.location`` is
    still exactly their governed province, so "an independent Hero
    standing here and commanding the garrison army here" is an
    unambiguous, structurally sound proxy for "governs this province" --
    a later turn's own Move orders could move such a Hero elsewhere
    (or an entirely different independent Hero could wander through),
    at which point this exact check would no longer mean the same
    thing.
    """

    for leader in state.leaders.values():
        if leader.kingdom_id is not None or leader.is_king or leader.location != coord:
            continue
        if any(army.commanded_by == leader.leader_id for army in state.armies_at(coord)):
            return leader.name
    return None


def _describe_neighbor_sentence(direction: Direction, coord: HexCoord, state: GameState) -> str | None:
    province = state.provinces.get(coord)
    if province is None:
        return None
    if province.race is Race.NO_RACE:
        # None of the 5 real samples this paragraph was sourced from
        # ever shows an uninhabited neighbor -- every real ArmyType
        # template below expects an actual race, so there's no sourced
        # text to render here rather than the broken "populated by no
        # races" this would otherwise produce. Omitted entirely, same
        # "nothing to say" convention as a missing province above.
        return None

    name = province.name if province.name else f"({coord.x}, {coord.y})"
    number = real_province_number(coord)
    terrain_name = TERRAIN_NAME[province.effective_terrain()]
    race_plural = RACE_PLURAL_NAME[province.race]
    race_adjective = RACE_ADJECTIVE[province.race]
    owner = state.kingdoms.get(province.owner_kingdom_id) if province.owner_kingdom_id is not None else None
    ruler_name = _leader_name(state, _king_leader_id(state, owner.kingdom_id)) if owner is not None else None
    if ruler_name is None:
        ruler_name = _independent_lord_ruler_name(state, coord)
    ending = _neighbor_ending(province.race, race_plural, race_adjective, province)

    if direction is Direction.NE:
        ruler_clause = f"{ruler_name} rules there" if ruler_name else "no one rules there"
        return (
            f"{_NEIGHBOR_OPENERS[direction]} a {terrain_name} area, which is known as {name} "
            f"(#{number}).  It is populated by {race_plural} and {ruler_clause}.  {ending}"
        )
    if direction is Direction.E:
        ruled_clause = f"It is ruled by {ruler_name}." if ruler_name else "It is ruled by no one."
        return (
            f"{_NEIGHBOR_OPENERS[direction]} a {terrain_name} area called {name} (#{number}), "
            f"populated by {race_plural}.  {ruled_clause}  {ending}"
        )
    if direction is Direction.SE:
        ruled_by = ruler_name if ruler_name else "no one"
        return (
            f"{_NEIGHBOR_OPENERS[direction]} the province of {name} (#{number}), ruled by {ruled_by}.  "
            f"It is said to be a {terrain_name} province inhabited by {race_plural}.  {ending}"
        )
    if direction is Direction.SW:
        reigns_clause = f"It is said that {ruler_name} reigns there." if ruler_name else "It is said that no one reigns there."
        return (
            f"{_NEIGHBOR_OPENERS[direction]} a {terrain_name} province known as {name} (#{number}).  "
            f"{reigns_clause}  It is known to be populated by {race_plural}.  {ending}"
        )
    if direction is Direction.W:
        rules_clause = f"where {ruler_name} rules" if ruler_name else "where no one rules"
        return (
            f"{_NEIGHBOR_OPENERS[direction]} a {terrain_name} province known as {name} (#{number}), "
            f"a land of {race_plural} {rules_clause}.  {ending}"
        )
    # Direction.NW
    ruled_by_clause = f"ruled by {ruler_name}" if ruler_name else "owned by no one"
    return (
        f"{_NEIGHBOR_OPENERS[direction]} {name} (#{number}), a {terrain_name} area {ruled_by_clause}, "
        f"where {race_plural} dwell.  {ending}"
    )


def describe_home_province_neighbors(state: GameState, kingdom_id: int) -> list[str]:
    """The Birthright (Turn 0) report's own home-province neighbor
    paragraph -- see the module-level Phase 981 comment above for the
    full sourcing, what's reproduced, and what's deliberately not.

    Returns an empty list when this Kingdom has no home province on
    record, or that coordinate isn't a real province in `state` -- the
    same "nothing to say, omit the section" convention every other
    composer here already follows.
    """

    kingdom = state.kingdoms.get(kingdom_id)
    if kingdom is None:
        return []
    home_coord = kingdom.home_province
    home_province = state.provinces.get(home_coord)
    if home_province is None:
        return []

    home_name = home_province.name if home_province.name else f"({home_coord.x}, {home_coord.y})"
    sentences = [f"The province of {home_name} belongs to your Majesty."]

    board_width = state.board_width
    board_height = state.board_height
    north_missing = neighbor_in_direction_wrapped(home_coord, Direction.NE, board_width, board_height) is None
    south_missing = neighbor_in_direction_wrapped(home_coord, Direction.SW, board_width, board_height) is None

    for direction in (Direction.NE, Direction.E, Direction.SE, Direction.SW, Direction.W, Direction.NW):
        if direction is Direction.NE and north_missing:
            continue  # dropped entirely -- NW's own sentence below covers "to the north" instead
        if direction is Direction.SE and south_missing:
            continue  # dropped entirely -- SW's own sentence below covers "to the south" instead
        if direction is Direction.NW and north_missing:
            sentences.append(_NORTH_ICE_CAP_LINE)
            continue
        if direction is Direction.SW and south_missing:
            sentences.append(_SOUTH_ICE_CAP_LINE)
            continue
        neighbor_coord = neighbor_in_direction_wrapped(home_coord, direction, board_width, board_height)
        if neighbor_coord is None:
            continue
        sentence = _describe_neighbor_sentence(direction, neighbor_coord, state)
        if sentence is not None:
            sentences.append(sentence)

    paragraph = "  ".join(sentences)
    return textwrap.wrap(paragraph, width=77, initial_indent="  ", subsequent_indent="")


# The real "royal scribe" intro (Phase 562), verbatim, confirmed
# byte-for-byte identical across every real sample checked this phase
# (`SE3__T1.K2`/`T4.K6`/`T5.K2` and others). Unlike every other section
# here, the real map has no standalone header of its own -- it's a
# direct continuation of PROVINCES, introduced by this one sentence
# after a blank-line gap, the same "no header" shape `ALIGNMENT
# REDUCTION`'s own real-vs-project-original distinction doesn't apply
# to here since this section genuinely has none in the source.
_MAP_REPORT_INTRO = "Sire, our royal scribe has drawn up a map of all neighboring lands:"

# REPORTS.PAS's own map key + caption, verbatim, byte-for-byte identical
# across every real sample checked this phase.
_MAP_KEY_LINE = "Key:   _ Plains   + Forest   & Jungle   ^ Mountain   . Desert     Sea"
_MAP_CAPTION_LINE_1 = "    In each province, the name and I.D. number of the province"
_MAP_CAPTION_LINE_2 = "  are listed above the ruler I.D and name."

# Phase 624: the real intro for every map page after the first, verbatim
# from real samples (e.g. `SE3__T5.K1`/`SE3__T10.K1`) -- see `report/
# ascii_map.py`'s own module docstring Phase 624 addendum for the full
# "far side of the world" pagination trigger this feeds.
_MAP_FAR_SIDE_INTRO = "We also drew up this map of lands on the far side of the world:"


def describe_map_report(state: GameState, kingdom_id: int) -> list[str]:
    """The real ASCII map (Phase 562) -- see `report/ascii_map.py`'s own
    module docstring for the full, sourced field-by-field derivation and
    exactly which real cases this phase does and doesn't reproduce.

    Returns an empty list when there are no provinces to render at all
    -- matching every other section composer's own "nothing to say,
    omit the section" convention, even though the real map has no
    header of its own for `compose_letter_report()` to conditionally
    skip the way it does for headered sections.

    Phase 577: `map_region_label()` -- "Ice cap" plus its own 78-dash
    rule, both real, sourced lines -- is inserted right after each
    page's own intro sentence's blank-line gap, before that page's own
    grid, exactly matching every real sample that shows it; omitted
    entirely (no gap left behind) for a page whose own topmost row
    doesn't reach the world's own northern edge.

    Phase 624: when the Kingdom's own known provinces span more columns
    than one page can print, the report splits into a "far side of the
    world" second (and further) page -- `report/ascii_map.py paginate_
    known_columns()`'s own home-anchored windowing decides which
    columns land on which page; see that function's own docstring and
    the module's Phase 624 addendum for the full sourcing.

    Phase 627: which of the 6 real layout tiers to use is now chosen by
    `select_layout_tier()`. Every page of a given report uses the same
    chosen tier, matching every real sample (a report's own far-side
    page never switches tiers mid-report).

    Phase 1038: `select_layout_tier()` is now fed `KingdomState.map_
    primary_region_columns` (this Kingdom's own tracked primary/"main"
    exploration region, see that field's own docstring) instead of the
    full known-column set whenever it's non-empty -- confirmed 100%
    accurate (54/54) against the real `tests/fixtures/reports/G3`
    corpus once fed the real main/far split, closing what the original
    Phase 627 labeled an 82%-accurate best-effort approximation. Falls
    back to the full known-column set (the original, still 82%-
    accurate approximation) for any `GameState` bridged cold from an
    existing snapshot, which has no way to backfill that real per-turn
    growth history -- see `select_layout_tier()`'s own docstring for
    the full account of why a snapshot alone can't recover it.

    Phase 628: only provinces this Kingdom actually knows about
    (`ProvinceState.known_to_kingdom()`, Phase 623) are rendered --
    previously every province in `state.provinces` rendered
    unconditionally, a real gap flagged since Phase 624 (see `report/
    ascii_map.py`'s own Phase 628 addendum). This filtered set also
    drives tier selection and pagination, not just the grid itself.

    Phase 871: the real `state.board_width` (not `report/ascii_map.py`'s
    own hardcoded 18-wide `DEFAULT_WIDTH`) now drives every cylindrical-
    wraparound computation here -- tier selection, pagination, and the
    grid itself -- closing a real, previously-shipped bug that silently
    mis-wrapped every Super-AK (30-wide, `GameState`'s own default) map.
    See `report/ascii_map.py`'s own Phase 871 addendum for the full
    account.
    """

    visible_provinces = {coord for coord, province in state.provinces.items() if province.known_to_kingdom(kingdom_id)}
    known_columns = {coord.x for coord in visible_provinces}
    if not known_columns:
        return []

    kingdom = state.kingdoms.get(kingdom_id)
    home_x = kingdom.home_province.x if kingdom is not None else min(known_columns)
    board_width = state.board_width

    # Phase 1038: feed tier selection only this Kingdom's own tracked
    # primary ("main") exploration-region columns when available -- see
    # `models/game_state.py KingdomState.map_primary_region_columns`'s
    # own docstring for why this closes most of `select_layout_tier()`'s
    # documented 82%-accuracy gap (a separately-grown far region can be
    # geometrically adjacent to the primary one with zero gap, which
    # would otherwise make the "uncapped home-anchored contiguous run"
    # swallow both into one oversized cluster). Empty for any `GameState`
    # bridged cold from an existing snapshot -- falls back to the full
    # `known_columns` set, exactly the old, honest approximation.
    primary_columns = kingdom.map_primary_region_columns if kingdom is not None else set()
    tier_input_columns = primary_columns if primary_columns else known_columns
    chosen_stride = select_layout_tier(tier_input_columns, home_x, board_width)
    renderer = next(render for stride, render in LAYOUT_TIERS if stride == chosen_stride)
    pages = paginate_known_columns(known_columns, home_x, max_columns_per_page(chosen_stride), board_width)

    lines: list[str] = ["", "", f"  {_MAP_REPORT_INTRO} ", ""]
    for page_index, page_columns in enumerate(pages):
        columns = set(page_columns)
        grid_lines = renderer(state, kingdom_id, columns=columns, visible_provinces=visible_provinces, board_width=board_width)
        region_label = map_region_label(state, columns=columns, visible_provinces=visible_provinces)
        region_lines = [region_label, MAP_REGION_LABEL_RULE] if region_label else []

        if page_index > 0:
            lines.extend([f"  {_MAP_FAR_SIDE_INTRO} ", ""])
        lines.extend(region_lines)
        lines.extend(grid_lines)

    lines.extend(
        [
            "",
            _MAP_KEY_LINE,
            _MAP_CAPTION_LINE_1,
            _MAP_CAPTION_LINE_2,
        ]
    )
    return lines


# HostAK/TP/REPORTS.PAS Rep_Leaders (~lines 658-855) -- the real
# "CHARACTERS" section's own sourced, verbatim opening, rejoined across
# its 3 raw WRITELN lines (same convention as _ARMIES_REPORT_OPENING).
# Quoted here even though this composer doesn't render everything the
# opening itself describes ("shows pay and abilities... move precedence
# and aptitude") -- the same "quote the real opening verbatim regardless
# of what actually renders below" precedent _FINANCES_OPENING already
# established.
_CHARACTERS_OPENING = (
    "My Lord, Great indeed are the leaders of our proud kingdom.  Though thee "
    "knows them well, I list them here for thy consideration (the first line "
    "shows pay and abilities; line 2 shows move precedence and aptitude.)"
)

_CHARACTERS_NONE_AT_PRESENT = "None at present"

# REPORTS.PAS Rep_Leaders (~lines 818-824) -- the real column-caption
