def _adventure_monster_label(monster: Monster) -> str:
    name = MONSTER_NAMES[monster]
    for prefix in _ADVENTURE_MONSTER_NAME_PREFIXES:
        if name.startswith(prefix):
            return name[len(prefix) :]
    return name


